 this.food=WantWorld.prototype.makeFood.call({kit:this.kit},'bread');this.food.position.set(0,1.05,0);fridge.add(this.food);this.meal=this.food.clone(true);this.meal.visible=false;g.add(this.meal);labelBoard('Fridge',0,4.1,.8,2.3,fridge);
